#[test]
fn test_push_answers_the_new_length_and_keeps_the_low_eight_bits() {
    let b: &mut crate::port::Buf = &mut crate::port::Buf::new();
    crate::testport::assert_eq(crate::port::buf_len(b), 0, "empty");
    crate::testport::assert_eq(crate::port::buf_push(b, 65), 1, "the first push answers 1");
    crate::testport::assert_eq(crate::port::buf_push(b, 511), 2, "the second answers 2");
    crate::testport::assert_eq(crate::port::buf_push(b, -1), 3, "and the third 3");
    crate::testport::assert_eq(crate::port::buf_push(b, 128), 4, "a byte with the high bit");
    crate::testport::assert_eq(crate::port::buf_push(b, 4660), 5, "0x1234 keeps 0x34");
    crate::testport::assert_eq(crate::port::buf_len(b), 5, "five bytes");
    crate::testport::assert_eq(crate::port::buf_at(b, 0), 65, "0 is 65");
    crate::testport::assert_eq(crate::port::buf_at(b, 1), 255, "511 is 255");
    crate::testport::assert_eq(crate::port::buf_at(b, 2), 255, "-1 is 255");
    crate::testport::assert_eq(crate::port::buf_at(b, 3), 128, "128 reads back as 128, not -128");
    crate::testport::assert_eq(crate::port::buf_at(b, 4), 52, "0x34");
}
#[test]
fn test_set_overwrites_one_byte() {
    let b: &mut crate::port::Buf = &mut crate::port::Buf::new();
    crate::port::buf_push(b, 1);
    crate::port::buf_push(b, 2);
    crate::port::buf_push(b, 3);
    crate::port::buf_set(b, 1, 300);
    crate::testport::assert_eq(crate::port::buf_at(b, 0), 1, "untouched");
    crate::testport::assert_eq(crate::port::buf_at(b, 1), 44, "300 keeps 44");
    crate::testport::assert_eq(crate::port::buf_at(b, 2), 3, "untouched");
    crate::testport::assert_eq(crate::port::buf_len(b), 3, "the length did not change");
}
#[test]
fn test_truncate_goes_to_a_length_and_pushes_resume_there() {
    let b: &mut crate::port::Buf = &mut crate::port::Buf::new();
    crate::port::buf_push(b, 10);
    crate::port::buf_push(b, 20);
    crate::port::buf_push(b, 30);
    crate::port::buf_truncate(b, 1);
    crate::testport::assert_eq(crate::port::buf_len(b), 1, "one left");
    crate::testport::assert_eq(crate::port::buf_push(b, 99), 2, "the next push answers 2");
    crate::testport::assert_eq(crate::port::buf_at(b, 1), 99, "and lands at 1");
    crate::port::buf_truncate(b, 0);
    crate::testport::assert_eq(crate::port::buf_len(b), 0, "emptied");
    crate::port::buf_truncate(b, 0);
    crate::testport::assert_eq(crate::port::buf_len(b), 0, "emptying an empty one is allowed");
}
#[test]
fn test_append_blob_copies_a_span() {
    let b: &mut crate::port::Buf = &mut crate::port::Buf::new();
    crate::port::buf_push(b, 7);
    crate::port::buf_append_blob(b, &crate::testport::hex_blob("00ff80aa55")[..], 1, 4);
    crate::testport::assert_eq(crate::port::buf_len(b), 4, "one and three");
    crate::testport::assert_eq(crate::port::buf_at(b, 0), 7, "the first byte");
    crate::testport::assert_eq(crate::port::buf_at(b, 1), 255, "ff");
    crate::testport::assert_eq(crate::port::buf_at(b, 2), 128, "80");
    crate::testport::assert_eq(crate::port::buf_at(b, 3), 170, "aa");
    crate::port::buf_append_blob(b, &crate::testport::hex_blob("0102")[..], 0, 0);
    crate::testport::assert_eq(crate::port::buf_len(b), 4, "an empty span appends nothing");
}
#[test]
fn test_it_grows_past_its_first_allocation() {
    let b: &mut crate::port::Buf = &mut crate::port::Buf::new();
    let mut i: i32 = 0;
    while i < 100000 {
        crate::port::buf_push(b, i);
        i += 1;
    }
    crate::testport::assert_eq(crate::port::buf_len(b), 100000, "100,000 bytes");
    crate::testport::assert_eq(crate::port::buf_at(b, 0), 0, "first");
    crate::testport::assert_eq(crate::port::buf_at(b, 255), 255, "255");
    crate::testport::assert_eq(crate::port::buf_at(b, 256), 0, "wraps: 256 is 0");
    crate::testport::assert_eq(crate::port::buf_at(b, 99999), 159, "99999 is 0x9F");
}
#[test]
fn test_blob_lends_the_contents() {
    let b: &mut crate::port::Buf = &mut crate::port::Buf::new();
    crate::port::buf_push(b, 1);
    crate::port::buf_push(b, 255);
    crate::port::buf_push(b, 128);
    crate::testport::assert_eq(crate::port::blob_len(crate::port::buf_blob(b)), 3, "three bytes");
    crate::testport::assert_eq(crate::port::blob_u8(crate::port::buf_blob(b), 0), 1, "1");
    crate::testport::assert_eq(crate::port::blob_u8(crate::port::buf_blob(b), 1), 255, "255");
    crate::testport::assert_eq(crate::port::blob_u8(crate::port::buf_blob(b), 2), 128, "128");
    crate::port::buf_push(b, 5);
    crate::testport::assert_eq(crate::port::blob_len(crate::port::buf_blob(b)), 4, "a borrow taken after a write sees it");
}
